import os,json,zstandard,re,hashlib
base=os.path.expanduser(r'~\.dsh\sessions')
dctx=zstandard.ZstdDecompressor()
# high precision: needs 密码/password AND a concrete value token nearby
pat=re.compile(r'(账\s*号|用户名|user\s*name|login|密\s*码|password|口\s*令)',re.I)
valpat=re.compile(r'(密\s*码|password|口\s*令)\s*[:：=为是]?\s*([A-Za-z0-9@._!#*\-]{4,})')
seen=set(); out=[]
def texts(o,acc):
    if isinstance(o,str): acc.append(o)
    elif isinstance(o,dict):
        # only user-ish roles
        role=str(o.get('role',o.get('type',''))).lower()
        for k,v in o.items():
            if k in ('role','type'): continue
            texts(v,acc)
    elif isinstance(o,list):
        for x in o: texts(x,acc)
for root,dirs,fs in os.walk(base):
    for fn in fs:
        if not fn.endswith('.jsonl.zstd'): continue
        try: data=dctx.stream_reader(open(os.path.join(root,fn),'rb')).read().decode('utf-8','replace')
        except: continue
        for ln in data.splitlines():
            if not pat.search(ln): continue
            try: o=json.loads(ln)
            except: continue
            # detect role
            role=''
            if isinstance(o,dict):
                for key in ('role','messageRole','speaker'):
                    if key in o: role=str(o[key]).lower()
                if 'message' in o and isinstance(o['message'],dict): role=str(o['message'].get('role','')).lower()
            if role and role not in ('user','human'): continue
            acc=[]; texts(o,acc)
            for t in acc:
                m=valpat.search(t)
                if not m: continue
                s=t.replace('\r',' ').replace('\n',' ').strip()
                s=s[:280]
                h=hashlib.md5(s.encode()).hexdigest()
                if h in seen: continue
                seen.add(h); out.append('[%s|%s] %s'%(os.path.basename(root)[:16],role or '?',s))
                if len(out)>=80: break
            if len(out)>=80: break
        if len(out)>=80: break
    if len(out)>=80: break
open(r'C:\Users\Administrator\AppData\Local\Temp\deploy_creds_precise.txt','w',encoding='utf-8').write('\n'.join(out))
print('precise hits',len(out),'from sessions scanned (stopped early if 80)')
